    private static int Compare(IReadOnlyList<object> a, IReadOnlyList<object> b)
    {
        for (var index = 0; index < a.Count; index++)
        {
            var order = Comparer<object>.Default.Compare(a[index], b[index]);
            if (order != 0) return order;
        }
        return 0;
    }

    private IEnumerable<Product> Visible() =>
        rows.Values.Where(row => true).OrderBy(KeyOf, Comparer<object[]>.Create((a, b) => Compare(a, b)));

    public Task<Product?> FindByIdAsync(string id)
    {
        return Task.FromResult(Visible().FirstOrDefault(row => Equals(row.Id, id)));
    }

    public Task<Page<Product>> ListAsync(int offset, int limit)
    {
        var rows = Visible().ToList();
        return Task.FromResult(new Page<Product>(rows.Skip(offset).Take(limit).ToList(), rows.Count, offset, limit));
    }

    public Task<Product> InsertAsync(Product entity)
    {
        entity.Id ??= MongoDB.Bson.ObjectId.GenerateNewId().ToString();
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task<Product> UpdateAsync(Product entity)
    {
        rows[KeyText(entity)] = entity;
        return Task.FromResult(entity);
    }

    public Task DeleteAsync(Product entity)
    {
        rows.Remove(KeyText(entity));
        return Task.CompletedTask;
    }

    public Task<Product?> AddPatternAsync(string id, MongoDB.Bson.BsonValue pattern)
    {
        var found = Visible().FirstOrDefault(row => Equals(row.Id, id));
        if (found is null) return Task.FromResult<Product?>(null);
        found.Patterns = [..found.Patterns ?? [], pattern];
        return Task.FromResult<Product?>(found);
    }

    public Task<Product?> RemovePatternAsync(string id, int position, int size)
    {
        var found = Visible().FirstOrDefault(row => Equals(row.Id, id));
        if (found is null || (found.Patterns?.Count ?? 0) != size) return Task.FromResult<Product?>(null);
        found.Patterns = (found.Patterns ?? []).Where((_, index) => index != position).ToList();
        return Task.FromResult<Product?>(found);
    }

    public Task<Product?> AddPartAsync(string id, Product.PartDocument part)
    {
        var found = Visible().FirstOrDefault(row => Equals(row.Id, id));
        if (found is null) return Task.FromResult<Product?>(null);
        found.Parts = [..found.Parts ?? [], part];
        return Task.FromResult<Product?>(found);
    }

    public Task<Product?> RemovePartAsync(string id, int position, int size)
    {
        var found = Visible().FirstOrDefault(row => Equals(row.Id, id));
        if (found is null || (found.Parts?.Count ?? 0) != size) return Task.FromResult<Product?>(null);
        found.Parts = (found.Parts ?? []).Where((_, index) => index != position).ToList();
        return Task.FromResult<Product?>(found);
    }
}

