using System.Runtime.CompilerServices;
using App;
using App.Common;
using App.Entities;
using App.Errors;
using MongoDB.Bson;
using MongoDB.Driver;

namespace App.Repositories;

/// <summary>Keeps audit-log documents in the database, through the MongoDB driver. Every write is stored at once.</summary>
public class MongoAuditLogRepository(Db db) : IAuditLogRepository
{
    private const string Collection = "audit-log";

    /// <summary>The document each entity was read from: a change writes only the fields that differ</summary>
    private static readonly ConditionalWeakTable<AuditLog, BsonDocument> Read = [];

    /// <summary>The fields a change may write</summary>
    private static readonly string[] Fields = ["at", "by"];

    public async Task<AuditLog?> FindByIdAsync(string id)
    {
        var found = await db.Find(Collection, Builders<AuditLog>.Filter.Eq(row => row.Id, id)).FirstOrDefaultAsync();
        return found is null ? null : Loaded(found);
    }

    public async Task<Page<AuditLog>> ListAsync(int offset, int limit)
    {
        var items = (await db.Find(Collection, Builders<AuditLog>.Filter.Empty).Sort(Builders<AuditLog>.Sort.Ascending(row => row.Id)).Skip(offset).Limit(limit).ToListAsync()).Select(Loaded).ToList();
        return new Page<AuditLog>(items, await db.CountAsync(Collection, Builders<AuditLog>.Filter.Empty), offset, limit);
    }

    public async Task<AuditLog> InsertAsync(AuditLog entity)
    {
        await db.InsertAsync("AuditLog", Collection, entity);
        return Loaded(entity);
    }

    public async Task<AuditLog> UpdateAsync(AuditLog entity)
    {
        var now = entity.ToBsonDocument();
        var changes = Documents.Changes(Read.TryGetValue(entity, out var before) ? before : null, now, Fields);
        if (changes.ElementCount > 0) await db.UpdateAsync<AuditLog>("AuditLog", Collection, new BsonDocument("_id", now["_id"]), changes);
        return Loaded(entity);
    }

    public async Task DeleteAsync(AuditLog entity)
    {
        await db.DeleteAsync("AuditLog", Collection, Builders<AuditLog>.Filter.Eq(row => row.Id, entity.Id));
    }

    /// <summary>The same entity, with what it is stored as kept to tell its changes.</summary>
    private static AuditLog Loaded(AuditLog entity)
    {
        Read.AddOrUpdate(entity, entity.ToBsonDocument());
        return entity;
    }
}

