        var before = created.Patterns?.Count ?? 0;
        MongoDB.Bson.BsonValue item = new MongoDB.Bson.BsonDocument("n", 7);
        var added = await service.AddPatternAsync(created.Id, item);
        Assert.Equal(before + 1, added.Patterns!.Count);
        var removed = await service.RemovePatternAsync(created.Id, before);
        Assert.Equal(before, removed.Patterns!.Count);
        await Assert.ThrowsAsync<NotFoundException>(() => service.RemovePatternAsync(created.Id, 99));
    }

    [Fact]
    public async Task AddsAndRemovesOneItemOfParts()
    {
        var service = new ProductService(uow);
        var row = Factories.NewProduct(1);
        var created = await service.CreateProductAsync(CreateOf(row));
        var before = created.Parts?.Count ?? 0;
        Product.PartDocument item = Factories.NewProductPart(7);
        var added = await service.AddPartAsync(created.Id, item);
        Assert.Equal(before + 1, added.Parts!.Count);
        var removed = await service.RemovePartAsync(created.Id, before);
        Assert.Equal(before, removed.Parts!.Count);
        await Assert.ThrowsAsync<NotFoundException>(() => service.RemovePartAsync(created.Id, 99));
    }

    /// <summary>The create DTO of a row the factories made.</summary>
    private static ProductCreate CreateOf(Product row) => new(row.Sku, row.Price, row.Stock, row.Weight, row.Big, row.Created, row.Reference, row.Picture, row.Key, row.Pattern, row.Patterns, row.Text, row.Parts, row.Low);
